#include "cloud.h"
#include <curl/curl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static int build_blob_url(const Vault *v,char*out,size_t cap){if(!v||!out||!v->cloud_url[0]||!v->cloud_object_id[0])return BALANCE_ERR;size_t n=strlen(v->cloud_url);const char*sep=(n&&v->cloud_url[n-1]=='/')?"":"/";int rc=snprintf(out,cap,"%s%sv1/blob/%s",v->cloud_url,sep,v->cloud_object_id);return rc>0&&(size_t)rc<cap?BALANCE_OK:BALANCE_ERR;}
int cloud_url_is_allowed(const char *url){if(!url)return 0;if(strncmp(url,"https://",8)==0)return 1;if(strncmp(url,"http://127.0.0.1",16)==0)return 1;if(strncmp(url,"http://localhost",16)==0)return 1;return 0;}
static size_t write_file(void *ptr,size_t sz,size_t nm,void*userdata){FILE*f=userdata;return fwrite(ptr,sz,nm,f);}
int cloud_put_history(const Vault*v,const Store*s){if(!v||!s||!v->cloud_enabled||!cloud_url_is_allowed(v->cloud_url))return BALANCE_ERR;struct stat st;if(stat(s->history_path,&st)!=0)return BALANCE_OK;FILE*f=fopen(s->history_path,"rb");if(!f)return BALANCE_ERR;char url[1024];if(build_blob_url(v,url,sizeof(url))!=BALANCE_OK){fclose(f);return BALANCE_ERR;}CURL*curl=curl_easy_init();if(!curl){fclose(f);return BALANCE_ERR;}struct curl_slist*headers=NULL;char auth[768];headers=curl_slist_append(headers,"Content-Type: application/octet-stream");if(v->cloud_token[0]){snprintf(auth,sizeof(auth),"Authorization: Bearer %s",v->cloud_token);headers=curl_slist_append(headers,auth);}curl_easy_setopt(curl,CURLOPT_URL,url);curl_easy_setopt(curl,CURLOPT_UPLOAD,1L);curl_easy_setopt(curl,CURLOPT_READFUNCTION,NULL);curl_easy_setopt(curl,CURLOPT_READDATA,f);curl_easy_setopt(curl,CURLOPT_INFILESIZE_LARGE,(curl_off_t)st.st_size);curl_easy_setopt(curl,CURLOPT_HTTPHEADER,headers);curl_easy_setopt(curl,CURLOPT_SSL_VERIFYPEER,1L);curl_easy_setopt(curl,CURLOPT_SSL_VERIFYHOST,2L);curl_easy_setopt(curl,CURLOPT_TIMEOUT,30L);CURLcode rc=curl_easy_perform(curl);long code=0;curl_easy_getinfo(curl,CURLINFO_RESPONSE_CODE,&code);curl_slist_free_all(headers);curl_easy_cleanup(curl);fclose(f);return rc==CURLE_OK&&(code==200||code==201)?BALANCE_OK:BALANCE_ERR;}
int cloud_get_history(const Vault*v,const Store*s){if(!v||!s||!v->cloud_enabled||!cloud_url_is_allowed(v->cloud_url))return BALANCE_ERR;char url[1024];if(build_blob_url(v,url,sizeof(url))!=BALANCE_OK)return BALANCE_ERR;char tmp[BALANCE_MAX_PATH];snprintf(tmp,sizeof(tmp),"%s.download",s->history_path);FILE*f=fopen(tmp,"wb");if(!f)return BALANCE_ERR;CURL*curl=curl_easy_init();if(!curl){fclose(f);unlink(tmp);return BALANCE_ERR;}struct curl_slist*headers=NULL;char auth[768];if(v->cloud_token[0]){snprintf(auth,sizeof(auth),"Authorization: Bearer %s",v->cloud_token);headers=curl_slist_append(headers,auth);}curl_easy_setopt(curl,CURLOPT_URL,url);curl_easy_setopt(curl,CURLOPT_WRITEFUNCTION,write_file);curl_easy_setopt(curl,CURLOPT_WRITEDATA,f);curl_easy_setopt(curl,CURLOPT_HTTPHEADER,headers);curl_easy_setopt(curl,CURLOPT_SSL_VERIFYPEER,1L);curl_easy_setopt(curl,CURLOPT_SSL_VERIFYHOST,2L);curl_easy_setopt(curl,CURLOPT_TIMEOUT,30L);CURLcode rc=curl_easy_perform(curl);long code=0;curl_easy_getinfo(curl,CURLINFO_RESPONSE_CODE,&code);curl_slist_free_all(headers);curl_easy_cleanup(curl);fclose(f);if(rc!=CURLE_OK||code!=200){unlink(tmp);return BALANCE_ERR;}if(rename(tmp,s->history_path)!=0){unlink(tmp);return BALANCE_ERR;}chmod(s->history_path,0600);return BALANCE_OK;}
